package com.bookeat.admin.service;
import com.bookeat.admin.dto.AdminRequests;import com.bookeat.admin.entity.Promotion;import com.bookeat.admin.repository.PromotionRepository;import com.bookeat.commerce.service.CommerceAccess;import com.bookeat.common.audit.AuditService;import com.bookeat.common.response.PageResponse;import com.bookeat.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.time.*;import java.math.*;
@Service @RequiredArgsConstructor @Transactional public class PromotionService {
 private final PromotionRepository promotions;private final CommerceAccess access;private final AuditService audit;private final JdbcTemplate jdbc;private final Clock clock;
 public record View(UUID id,long version,String code,String title,String kind,UUID restaurantId,String serviceType,BigDecimal minimumAmount,BigDecimal discountPercent,BigDecimal maximumDiscount,int maximumUses,int uses,Instant effectiveFrom,Instant effectiveUntil,boolean active){}
 public record Quote(String code,BigDecimal discount,BigDecimal amountAfterDiscount,boolean reserved){}
 public View create(UUID actor,String kind,AdminRequests.Promotion q){if(!Set.of("OFFER","COUPON").contains(kind)||!q.effectiveUntil().isAfter(q.effectiveFrom()))throw new ApiException(ErrorCode.VALIDATION_FAILED);if(q.restaurantId()!=null)access.lock(q.restaurantId());var p=new Promotion();p.setCode(q.code());p.setTitle(q.title());p.setKind(kind);p.setRestaurantId(q.restaurantId());p.setServiceType(q.serviceType()==null?null:q.serviceType().name());p.setMinimumAmount(q.minimumAmount());p.setDiscountPercent(q.discountPercent());p.setMaximumDiscount(q.maximumDiscount());p.setMaximumUses(q.maximumUses());p.setUses(0);p.setEffectiveFrom(q.effectiveFrom());p.setEffectiveUntil(q.effectiveUntil());p.setActive(q.active());promotions.saveAndFlush(p);audit.record(actor,kind+"_CREATED","Promotion",p.getId(),null);return view(p);}
 @Transactional(readOnly=true) public PageResponse<View> list(String kind,int page,int size){return PageResponse.from(promotions.findByKind(kind,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt","id"))).map(this::view));}
 public View disable(UUID actor,UUID id,AdminRequests.Action q){var p=promotions.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.version(p.getVersion(),q.version());p.setActive(false);promotions.flush();audit.record(actor,"PROMOTION_DISABLED","Promotion",id,null);return view(p);}
 public Quote quote(UUID actor,AdminRequests.Coupon q){UUID c=access.customer(actor);var p=find(q.code());BigDecimal discount=discount(p,c,q.restaurantId(),q.serviceType().name(),q.amount());return new Quote(q.code(),discount,q.amount().subtract(discount),false);}
 public BigDecimal redeem(String code,UUID customer,UUID restaurant,String service,BigDecimal amount,UUID payment){var p=promotions.lockByCode(code).orElseThrow(()->new ApiException(ErrorCode.PROMOTION_INVALID));BigDecimal discount=discount(p,customer,restaurant,service,amount);jdbc.update("insert into promotion_redemptions(promotion_id,customer_id,payment_id,discount_amount) values(?,?,?,?)",p.getId(),customer,payment,discount);p.setUses(p.getUses()+1);promotions.flush();return discount;}
 @Transactional(readOnly=true) public List<View> customerOffers(){Instant now=clock.instant();return promotions.findAll().stream().filter(p->"OFFER".equals(p.getKind())&&p.isActive()&&!now.isBefore(p.getEffectiveFrom())&&now.isBefore(p.getEffectiveUntil())&&p.getUses()<p.getMaximumUses()).sorted(Comparator.comparing(Promotion::getEffectiveUntil).thenComparing(Promotion::getId)).map(this::view).toList();}
 private Promotion find(String code){return promotions.findByCode(code).orElseThrow(()->new ApiException(ErrorCode.PROMOTION_INVALID));}
 private BigDecimal discount(Promotion p,UUID customer,UUID restaurant,String service,BigDecimal amount){if(!p.isActive()||clock.instant().isBefore(p.getEffectiveFrom())||!clock.instant().isBefore(p.getEffectiveUntil())||p.getUses()>=p.getMaximumUses()||amount.compareTo(p.getMinimumAmount())<0||p.getRestaurantId()!=null&&!p.getRestaurantId().equals(restaurant)||p.getServiceType()!=null&&!p.getServiceType().equals(service)||Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from promotion_redemptions where promotion_id=? and customer_id=?)",Boolean.class,p.getId(),customer)))throw new ApiException(ErrorCode.PROMOTION_INVALID);return amount.multiply(p.getDiscountPercent()).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP).min(p.getMaximumDiscount()).min(amount.subtract(new BigDecimal("0.01")).max(BigDecimal.ZERO));}
 private View view(Promotion p){return new View(p.getId(),p.getVersion(),p.getCode(),p.getTitle(),p.getKind(),p.getRestaurantId(),p.getServiceType(),p.getMinimumAmount(),p.getDiscountPercent(),p.getMaximumDiscount(),p.getMaximumUses(),p.getUses(),p.getEffectiveFrom(),p.getEffectiveUntil(),p.isActive());}
}
